from ...base.client import BaseClient


class SmsMethods(BaseClient):
    """
    Методы группы 'Смс' из https://im-docs.corp.mail.ru/
    """

    async def rapi_sendNotifySms(self, smsNotifyContext: str):
        """
        При помощи этого метода происходит отправка смс,
        если ранее клиент получил ивент suggestToNotifyUser,
        с smsNotifyContext.
        :param smsNotifyContext:
        :return: тело ответа сервера
        """
        return await self.post(
            "rapi/sendNotifySms",
            json={
                "reqId": self.getReqId(),
                "aimsid": self.aimsid,
                "params": {"smsNotifyContext": smsNotifyContext},
            },
        )
